import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner, address newOwner2) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner2 != address(0));
        vm.assume(newOwner != newOwner2);
