pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(this));
        vm.assume(newOwner != address(0));
        // a call from a NON-owner must not change owner
        address attacker = makeAddr("attacker");
        vm.assume(attacker != address(this));
        vm.prank(attacker);
        try c.setOwner(newOwner) {
            // call succeeded; rule: owner must be unchanged
            assertTrue(c.owner() == address(this), "non-owner changed owner");
        } catch {
            // call reverted; rule: owner unchanged
            assertTrue(c.owner() == address(this), "owner changed on revert");
        }
    }
}

