// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner) public {
        // Admissible domain: the full address space, including address(0).
        // Only the current owner may call setOwner; setUp deployed c with
        // this test contract as owner, so no assume/bound is needed.
        vm.prank(address(this));
        bool ok;
        bool returnedTrue;
        try c.setOwner(newOwner) returns (bool success) {
            ok = true;
            returnedTrue = success;
        } catch {
            ok = false;
            returnedTrue = false;
        }
        // Universal rule: for ANY proposed owner (zero address included),
        // an owner-issued setOwner never reverts, reports success, and
        // actually installs that address as the new owner.
        assertTrue(ok && returnedTrue && c.owner() == newOwner);
    }
}
